package io.github.testlens.migration.tooling;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import static org.junit.jupiter.api.Assertions.*;

class MigrationVerificationPlanTest {
    @TempDir Path temporary;
    @Test void exactApplyRequirementDigestIsMandatoryAndStricterRequirementsMayOnlyAdd(){
        var compile=req("COMPILE_AFFECTED_MODULE",MigrationVerificationPlan.StageType.COMPILE,MigrationRunPlan.ExecutionMode.CUSTOM_TRUSTED,"module-a","a");MigrationApplyPlan apply=apply(List.of(compile));String tx=MigrationApplyTransaction.id(apply);var structure=req("STRICTER_SOURCE_STRUCTURE",MigrationVerificationPlan.StageType.SOURCE_STRUCTURE,null,"src/A.java","a");var plan=MigrationVerificationPlan.create(apply,tx,cp(),source(),List.of(compile),List.of(structure),List.of(),List.of(),List.of(),List.of(),List.of(),null);assertEquals(2,plan.requirements().size());assertEquals(List.of(MigrationVerificationPlan.StageType.SOURCE_STRUCTURE,MigrationVerificationPlan.StageType.COMPILE),plan.stages().stream().map(MigrationVerificationPlan.Stage::type).toList());
        var wrong=req("RUN_HEADLESS",MigrationVerificationPlan.StageType.HEADLESS,MigrationRunPlan.ExecutionMode.HEADLESS_STANDARD,"test-a","a");assertThrows(IllegalArgumentException.class,()->MigrationVerificationPlan.create(apply,tx,cp(),source(),List.of(wrong),List.of(),List.of(),List.of(),List.of(),List.of(),List.of(),null));
    }
    @Test void semanticDedupMergesProposalCoverageButKeepsExecutionModesDistinct(){
        var a=req("RUN_HEADLESS",MigrationVerificationPlan.StageType.HEADLESS,MigrationRunPlan.ExecutionMode.HEADLESS_STANDARD,"test-a","a");var b=req("RUN_HEADLESS",MigrationVerificationPlan.StageType.HEADLESS,MigrationRunPlan.ExecutionMode.HEADLESS_STANDARD,"test-a","b");var fast=req("RUN_HEADLESS_FAST",MigrationVerificationPlan.StageType.FAST,MigrationRunPlan.ExecutionMode.HEADLESS_FAST,"test-a","b");MigrationApplyPlan apply=apply(List.of(a,b,fast));var plan=MigrationVerificationPlan.create(apply,MigrationApplyTransaction.id(apply),cp(),source(),List.of(a,b,fast),List.of(),List.of(),List.of(),List.of(),List.of(),List.of(),null);assertEquals(2,plan.requirements().size());var headless=plan.requirements().stream().filter(x->x.stageType()==MigrationVerificationPlan.StageType.HEADLESS).findFirst().orElseThrow();assertEquals(List.of(proposal("a"),proposal("b")),headless.proposalIds());assertNotEquals(plan.requirements().get(0).executionMode(),plan.requirements().get(1).executionMode());
    }
    @Test void wrapperMainBindsExactJarAndPropertiesAndNeverFallsBackToWindowsScript()throws Exception{
        Path root=temporary.resolve("project");Path wrapper=root.resolve("gradle/wrapper");Files.createDirectories(wrapper);Files.write(wrapper.resolve("gradle-wrapper.jar"),new byte[]{1,2,3});Files.writeString(wrapper.resolve("gradle-wrapper.properties"),"distributionUrl=https://user:secret@example.invalid/gradle.zip?token=x\n");MigrationJavaWrapperMain adapter=new MigrationJavaWrapperMain();var binding=adapter.inspect(root,MigrationVerificationPlan.WrapperBinding.WrapperKind.GRADLE_WRAPPER_MAIN,"trusted-java");List<String>args=adapter.commandArguments(root,binding,List.of("--offline","test"));assertEquals("org.gradle.wrapper.GradleWrapperMain",args.get(2));assertTrue(args.contains("--offline"));assertFalse(args.stream().anyMatch(x->x.endsWith(".cmd")||x.endsWith(".bat")||x.endsWith(".ps1")));assertFalse(MigrationJavaWrapperMain.sanitizedDistributionUrl(Files.readAllBytes(wrapper.resolve("gradle-wrapper.properties"))).contains("secret"));assertTrue(MigrationVerificationService.offline(binding.kind(),List.of("--offline")));assertFalse(MigrationVerificationService.offline(binding.kind(),List.of("test")));assertTrue(MigrationVerificationService.offline(MigrationVerificationPlan.WrapperBinding.WrapperKind.MAVEN_WRAPPER_MAIN,List.of("-o")));assertThrows(IllegalArgumentException.class,()->MigrationVerificationPlan.TrustedRunBinding.create(domain("migration-verification-stage-v1","9"),domain("migration-run-plan-v1","a"),cp(),binding,MigrationVerificationPlan.NetworkPolicy.NETWORK_NOT_REQUIRED));String worktree=domain("migration-worktree-binding-v1","2");var run=MigrationRunPlan.create("trusted-java",args,worktree,java.util.Map.of(),List.of(),java.time.Duration.ofSeconds(10),MigrationRunPlan.OutputBounds.defaults(),List.of(),MigrationRunPlan.ExecutionMode.CUSTOM_TRUSTED,MigrationRunPlan.Scope.CUSTOM_TRUSTED,MigrationRunPlan.SideEffectClassification.UNKNOWN,cp(),MigrationRunPlan.BaselineRole.VARIANT);Path javaExe=Path.of(System.getProperty("java.home"),"bin",System.getProperty("os.name").toLowerCase().contains("win")?"java.exe":"java");var local=new MigrationTrustedProcessRunner.LocalExecution("trusted-java",javaExe,root,worktree,null);var service=new MigrationVerificationService();assertTrue(service.wrapperRunMatches(root,binding,run,local));var wrongRun=MigrationRunPlan.create("trusted-java",List.of("-version"),worktree,java.util.Map.of(),List.of(),java.time.Duration.ofSeconds(10),MigrationRunPlan.OutputBounds.defaults(),List.of(),MigrationRunPlan.ExecutionMode.CUSTOM_TRUSTED,MigrationRunPlan.Scope.CUSTOM_TRUSTED,MigrationRunPlan.SideEffectClassification.UNKNOWN,cp(),MigrationRunPlan.BaselineRole.VARIANT);assertFalse(service.wrapperRunMatches(root,binding,wrongRun,local));Files.write(wrapper.resolve("gradle-wrapper.jar"),new byte[]{9});assertThrows(MigrationJavaWrapperMain.StaleWrapper.class,()->adapter.revalidate(root,binding));Path missing=temporary.resolve("missing");Files.createDirectory(missing);assertThrows(MigrationJavaWrapperMain.UnsupportedLayout.class,()->adapter.inspect(missing,MigrationVerificationPlan.WrapperBinding.WrapperKind.MAVEN_WRAPPER_MAIN,"trusted-java"));
    }
    @Test void resultIsContentDerivedAndOptionalNotRunDoesNotPreventVerified(){var r=req("COMPILE_AFFECTED_MODULE",MigrationVerificationPlan.StageType.COMPILE,null,"module","a");MigrationApplyPlan apply=apply(List.of(r));var stage=r.stage();var passed=new MigrationVerificationResult.StageResult(stage.stageRef(),stage.type(),MigrationVerificationPlan.Necessity.REQUIRED,MigrationVerificationResult.StageStatus.PASSED,null,List.of(),List.of());var optionalStage=MigrationVerificationPlan.Stage.create(MigrationVerificationPlan.StageType.FAST,MigrationVerificationPlan.Necessity.OPTIONAL,"test",List.of(r.requirementRef()),MigrationVerificationPlan.Expectation.TEST_PASS);var optional=new MigrationVerificationResult.StageResult(optionalStage.stageRef(),optionalStage.type(),optionalStage.necessity(),MigrationVerificationResult.StageStatus.NOT_RUN,null,List.of(),List.of());String tx=MigrationApplyTransaction.id(apply),plan="migration-verification-plan-v1:sha256:"+"e".repeat(64);var one=MigrationVerificationResult.create(tx,apply.applyPlanId(),plan,cp(),MigrationVerificationResult.Status.VERIFIED,List.of(passed,optional),List.of(),List.of(),List.of(),List.of(),List.of(),List.of(),null);var two=MigrationVerificationResult.create(tx,apply.applyPlanId(),plan,cp(),MigrationVerificationResult.Status.VERIFIED,List.of(passed,optional),List.of(),List.of(),List.of(),List.of(),List.of(),List.of(),null);assertEquals(one.verificationResultId(),two.verificationResultId());assertEquals(1,one.requiredPassed());assertEquals(1,one.requiredTotal());}
    @Test void strictTypedCodecRoundTripsAndRejectsDuplicates(){var requirement=req("COMPILE_AFFECTED_MODULE",MigrationVerificationPlan.StageType.COMPILE,null,"module","a");MigrationApplyPlan apply=apply(List.of(requirement));var plan=MigrationVerificationPlan.create(apply,MigrationApplyTransaction.id(apply),cp(),source(),List.of(requirement),List.of(),List.of(),List.of(),List.of(),List.of(),List.of(),null);var stage=new MigrationVerificationResult.StageResult(plan.stages().get(0).stageRef(),MigrationVerificationPlan.StageType.COMPILE,MigrationVerificationPlan.Necessity.REQUIRED,MigrationVerificationResult.StageStatus.PASSED,null,List.of(),List.of());var result=MigrationVerificationResult.create(plan.transactionId(),apply.applyPlanId(),plan.verificationPlanId(),cp(),MigrationVerificationResult.Status.VERIFIED,List.of(stage),List.of(),List.of(),List.of(),List.of(),List.of(),List.of(),null);MigrationVerificationJson json=new MigrationVerificationJson();assertEquals(plan,json.readPlan(json.write(plan)));assertEquals(result,json.readResult(json.write(result)));String bytes=new String(json.write(plan),java.nio.charset.StandardCharsets.UTF_8);assertThrows(IllegalArgumentException.class,()->json.readPlan(bytes.replaceFirst("\\{","{\"schemaVersion\":1,").getBytes(java.nio.charset.StandardCharsets.UTF_8)));}
    private static MigrationVerificationPlan.Requirement req(String kind,MigrationVerificationPlan.StageType type,MigrationRunPlan.ExecutionMode mode,String target,String proposal){return MigrationVerificationPlan.Requirement.create(kind,type,MigrationVerificationPlan.Necessity.REQUIRED,target,null,mode,MigrationProposal.SideEffect.UNKNOWN,type==MigrationVerificationPlan.StageType.COMPILE?MigrationVerificationPlan.Expectation.COMMAND_SUCCESS:MigrationVerificationPlan.Expectation.TEST_PASS,MigrationVerificationPlan.SourceScope.PROJECT_SOURCE,List.of(proposal(proposal)));}
    private static MigrationApplyPlan apply(List<MigrationVerificationPlan.Requirement>requirements){return MigrationApplyPlan.create(domain("migration-repository-binding-v1","1"),domain("migration-worktree-binding-v1","2"),domain("migration-proposal-set-v1","3"),requirements.stream().flatMap(x->x.proposalIds().stream()).distinct().toList(),domain("migration-decision-ledger-v1","4"),List.of(),List.of(),List.of(),cp(),cp(),List.of(),MigrationVerificationPlan.requirementsDigest(requirements),0,0,"apply/diffs/plan.patch","sha256:"+"5".repeat(64),0,MigrationApplyPlan.MAX_DIFF_BYTES,List.of());}
    private static String proposal(String suffix){return domain("migration-proposal-v1",suffix.equals("a")?"a":"b");}private static String cp(){return domain("migration-checkpoint-v1","c");}private static String source(){return domain("migration-source-state-v1","d");}private static String domain(String d,String c){return d+":sha256:"+c.repeat(64);}
}
